 "content": "def transform(grid):
    out=[row[:] for row in grid]
    marks=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==7]
    if not marks:return out
    r0,r1=min(r for r,c in marks),max(r for r,c in marks)
    c0,c1=min(c for r,c in marks),max(c for r,c in marks)
    shape={(r-r0,c-c0) for r,c in marks}
    h,w=r1-r0+1,c1-c0+1
    # Locate occurrences of the marked-cell pattern in the dominant background color.
    for br in range(len(grid)-h+1):
        for bc in range(len(grid[0])-w+1):
            if all(grid[br+dr][bc+dc]==1 for dr,dc in shape):
                for dr,dc in shape:
                    out[br+dr][bc+dc]=7
    return out
